def to_degrees(text):
    return int(text[:2]) + float(text[2:]) / 60


def parse_lat(sentence):
    fields = sentence.split(",")
    return to_degrees(fields[2])


print(parse_lat("$GPGGA,123519,4807.038,N,01131.000,E,1,08,0.9,545.4,M,46.9,M,,*47"))
